struct Pair {
    var a: Int
    var b: Int
}

func swapValues(_ x: inout Int, _ y: inout Int) {
    let temp = x
    x = y
    y = temp
}

class Box {
    var pair = Pair(a: 1, b: 2)
    func safeSwap() {
        var local = pair
        swapValues(&local.a, &local.b)
        pair = local
        print(pair.a, pair.b)
    }
}
Box().safeSwap()

